-- Batch 13 (verses 651-700)
INSERT INTO "Verse" (id,"chapterId",number,"globalNumber",slug,sanskrit,transliteration,"wordByWord",translation,"translationAuthor",commentary,"commentaryAuthor","createdAt","updatedAt")
VALUES
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',28,651,'18-28','अयुक्तः प्राकृतः स्तब्धः शठो नैष्कृतिकोऽलसः।विषादी दीर्घसूत्री च कर्ता तामस उच्यते।।18.28।।','ayuktaḥ prākṛitaḥ stabdhaḥ śhaṭho naiṣhkṛitiko ‘lasaḥ
viṣhādī dīrgha-sūtrī cha kartā tāmasa uchyate',to_json('ayuktaḥ—undisciplined; prākṛitaḥ—vulgar; stabdhaḥ—obstinate; śhaṭhaḥ—cunning; naiṣhkṛitikaḥ—dishonest or vile; alasaḥ—slothful; viṣhādī—unhappy and morose; dīrgha-sūtrī—procrastinating; cha—and; kartā—performer; tāmasaḥ—in the mode of ignorance; uchyate—is said to be'::text),'Unsteady, vulgar, inflexible, deceitful, malicious, lazy, despondent, and procrastinating—such an agent is called Tamasic.','Swami Sivananda','18.28 अयुक्तः unsteady? प्राकृतः vulgar? स्तब्धः unbending? शठः cheating? नैष्कृतिकः malicious? अलसः lazy? विषादी desponding? दीर्घसूत्री procrastinating? च and? कर्ता agent? तामसः Tamasic (dark)? उच्यते is said.Commentary Owing to his vulgar nature he is not able to discriminate between proper and improper actions. His heart is filled with vanity. He will never prostrate himself before the deity or a sage. He is very stiff and unbending in his demeanour. He is the very embodiment of deceit? the abode of the passion for gambling and all such vices. He is ever ready to do evil actions. When an opportunity for his doing good occurs? he is utterly slothful and inactive? but he is very alert in doing evil.Prakritah Vulgar Quite uncultured in intellect one who is childish.Stabdhah Unbending (like a stick)? not bowing down to anybody.Shathah Cheating concealing his real nature.Naishkritikah Creating arrels and disputes among the people.Alasah Lazy Not doing even that which ought to be done.Dirghasutri Postponing duties too long always slothful not performing even in a month what ought to be done today or tomorrow.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',29,652,'18-29','बुद्धेर्भेदं धृतेश्चैव गुणतस्त्रिविधं श्रृणु।प्रोच्यमानमशेषेण पृथक्त्वेन धनञ्जय।।18.29।।','buddher bhedaṁ dhṛiteśh chaiva guṇatas tri-vidhaṁ śhṛiṇu
prochyamānam aśheṣheṇa pṛithaktvena dhanañjaya',to_json('buddheḥ—of intellect; bhedam—the distinctions; dhṛiteḥ—of determination; cha—and; eva—certainly; guṇataḥ tri-vidham—according to the three modes of material nature; śhṛiṇu—hear; prochyamānam—described; aśheṣheṇa—in detail; pṛithaktvena—distinctly; dhanañjaya—conqueror of wealth, Arjun'::text),'Hear thou the threefold division of intellect and firmness, according to the Gunas, as I declare them fully and distinctly, O Arjuna.','Swami Sivananda','18.29 बुद्धेः of intellect? भेदम् division? धृतेः of firmness? च and? एव even? गुणतः according to alities? त्रिविधम् threefold? श्रृणु hear? प्रोच्यमानम् as I declare? अशेषेण fully? पृथक्त्वेन distinctly? धनञ्जय O Dhananjaya.Commentary Dhananjaya The coneror of wealth Arjuna is so called because he acired much material and spiritual wealth during his tours of conest (Digvijaya) to the four arters of the earth.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',30,653,'18-30','प्रवृत्तिं च निवृत्तिं च कार्याकार्ये भयाभये।बन्धं मोक्षं च या वेत्ति बुद्धिः सा पार्थ सात्त्विकी।।18.30।।','pravṛittiṁ cha nivṛittiṁ cha kāryākārye bhayābhaye
bandhaṁ mokṣhaṁ cha yā vetti buddhiḥ sā pārtha sāttvikī',to_json('pravṛittim—activities; cha—and; nivṛittim—renuncation from action; cha—and; kārya—proper action; akārye—improper action; bhaya—fear; abhaye—without fear; bandham—what is binding; mokṣham—what is liberating; cha—and; yā—which; vetti—understands; buddhiḥ—intellect; sā—that; pārtha—son of Pritha; sāttvikī—in the nature of goodness'::text),'The intellect which knows the path of work and renunciation, what should be done and what should not be done, fear and fearlessness, bondage and liberation—that intellect is Sattvic (pure), O Arjuna.','Swami Sivananda','18.30 प्रवृत्तिम् action? the path of work? च and? निवृत्तिम् the path of renunciation? च and? कार्याकार्ये what ought to be done and what ought not to be done? भयाभये fear and fearlessness? बन्धम् bondage? मोक्षम् liberation? च and? या which? वेत्ति knows? बुद्धिः intellect? सा that? पार्थ O Arjuna? सात्त्विकी Sattvic.Commentary The threefold nature of knowledge has been described already (verse 22 above). Now the threefold nature of the intellect is described. Knowledge is different from the intellect.Pravritti Action The cause of bondage the path of action. Nivritti Inaction The cause of liberation the path of renunciation the path of Sannyasa.Karyakarye The pure intellect knows what ought to be done and what ought not to be done at,particular places and times it knows the actions that produce visible or invisible results? that are enjoined or prohibited by the scriptures. It guides a man who relies on the scriptural ordinances for his daily conduct of life.Bhayabhaye Fear and fearlessness The cause of fear and fearlessness either visible or invisible.Bandham moksham Bondage and liberation together with their causes.Knowledge is a Vritti (function or state) of the intellect whereas intellect is what functions or undergoes the change of state. Even firmness is only a particular Vritti (modification or state) of the intellect. (Cf.XVIII.20)','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',31,654,'18-31','यया धर्ममधर्मं च कार्यं चाकार्यमेव च।अयथावत्प्रजानाति बुद्धिः सा पार्थ राजसी।।18.31।।','yayā dharmam adharmaṁ cha kāryaṁ chākāryam eva cha
ayathāvat prajānāti buddhiḥ sā pārtha rājasī',to_json('yayā—by which; dharmam—righteousness; adharmam—unrighteousness; cha—and; kāryam—right conduct; cha—and; akāryam—wrong conduct; eva—certainly; cha—and; ayathā-vat—confused; prajānāti—distinguish; buddhiḥ—intellect; sā—that; pārtha—Arjun, the son of Pritha; rājasī—in the mode of passion'::text),'That by which one wrongly understands dharma and adharma, and also what ought to be done and what ought not to be done—that intellect, O Arjuna, is rajasic (passionate).','Swami Sivananda','18.31 यया by which? धर्मम् Dharma? अधर्मम् Adharma? च and? कार्यम् what ought to be done? च and? अकार्यम् what ought not to be done? एव even? च and? अयथावत् wrongly? प्रजानाति understands? बुद्धिः intellect? सा that? पार्थ O Partha? राजसी Rajasic (passionate).Commentary There is no proper eivalent in the English language for the word Dharma. Duty? righteousness? virtue? law are very poor translations of the word. That which elevates you and takes you to the goal? i.e.? Brahman or the Self? is Dharma. That which hurls you down into the dark abyss of ignorance is Adharma. What is ordained in the scriptures is Dharma what is prohibited by them is Adharma. A Rajasic intellect is not able to distinguish between right and wrong or to understand the difference between righteous and unrighteous actions.Ayathavat Wrongly Contrary to what is determined by all authorities or men of wisdom or to the highest knowledge.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',32,655,'18-32','अधर्मं धर्ममिति या मन्यते तमसाऽऽवृता।सर्वार्थान्विपरीतांश्च बुद्धिः सा पार्थ तामसी।।18.32।।','adharmaṁ dharmam iti yā manyate tamasāvṛitā
sarvārthān viparītānśh cha buddhiḥ sā pārtha tāmasī',to_json('adharmam—irreligion; dharmam—religion; iti—thus; yā—which; manyate—imagines; tamasa-āvṛitā—shrouded in darkness; sarva-arthān—all things; viparītān—opposite; cha—and; buddhiḥ—intellect; sā—that; pārtha—Arjun, the son of Pritha; tāmasī—of the nature of ignorance'::text),'That intellect, O Arjuna, which is enveloped in darkness and sees Adharma as Dharma and all things perverted, is Tamasic (dark).','Swami Sivananda','18.32 अधर्मम् Adharma? धर्मम् Dharma? इति thus? या which? मन्यते thinks? तमसा by darkness? आवृता enveloped? सर्वार्थान् all things? विपरीतान् perverted? च and? बुद्धिः intellect? सा that? पार्थ O Partha? तामसी Tamasic (dark).Commentary That intellect which regards righteous acts as evil? and considers right things to be false? which treats everything in a contrary sense and looks upon virtues as if they were vices and takes everything that the scriptures declare to be good as being entirely wrong? is Tamasic. It views all things in a perverted light.Thus? O Arjuna? I have explained to thee the three aspects of the intellect. Now listen to the explanation of the characteristics of the three aspects of firmness.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',33,656,'18-33','धृत्या यया धारयते मनःप्राणेन्द्रियक्रियाः।योगेनाव्यभिचारिण्या धृतिः सा पार्थ सात्त्विकी।।18.33।।','dhṛityā yayā dhārayate manaḥ-prāṇendriya-kriyāḥ
yogenāvyabhichāriṇyā dhṛitiḥ sā pārtha sāttvikī',to_json('dhṛityā—by determining; yayā—which; dhārayate—sustains; manaḥ—of the mind; prāṇa—life-airs; indriya—senses; kriyāḥ—activities; yogena—through Yog; avyabhichāriṇyā—with steadfastness; dhṛitiḥ—determination; sā—that; pārtha—Arjun, the son of Pritha; sāttvikī—in the mode of goodness'::text),'The unwavering firmness, through which Yoga restrains the functions of the mind, life-force, and senses—that firmness, O Arjuna, is Sattvic (pure).','Swami Sivananda','18.33 धृत्या by firmness? यया (by) which? धारयते holds? मनःप्राणेन्द्रियक्रियाः the functions of the mind? the Prana and the senses? योगेन by Yoga? अव्यभिचारिण्या unswerving? धृतिः firmness? सा that? पार्थ O Arjuna? सात्त्विकी Sattvic (pure).Commentary When firmness is awakened in the mind? the activities of the mind? the lifeforce and the senses are brought under control. The senses are withdrawn into the mind. The Prana and the Apana pass into the Sushumna Nadi.Yoga Samadhi or concentration of the mind. You cannot restrain the mind? the lifeforce and the senses by mere firmness. You can control them only by firmness which is ever accompanied by concentration of the mind.When the mind? the lifeforce and the senses are curbed by unwarvering firmness? they cannot run towards external sensual objects? they cannot do any mischief? they cannot move in ways which are opposed to the scriptures? they will be absorbed into their respective causes and their outgoing tendencies will be totally checked.This firmness is not repression or suppression? but an intelligent sublimation and inner transformation.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',34,657,'18-34','यया तु धर्मकामार्थान् धृत्या धारयतेऽर्जुन।प्रसङ्गेन फलाकाङ्क्षी धृतिः सा पार्थ राजसी।।18.34।।','yayā tu dharma-kāmārthān dhṛityā dhārayate ‘rjuna
prasaṅgena phalākāṅkṣhī dhṛitiḥ sā pārtha rājasī',to_json('yayā—by which; tu—but; dharma-kāma-arthān—duty, pleasures, and wealth; dhṛityā—through steadfast will; dhārayate—holds; arjuna—Arjun; prasaṅgena—due of attachment; phala-ākāṅkṣhī—desire for rewards; dhṛitiḥ—determination; sā—that; pārtha—Arjun, the son of Pritha; rājasī—in the mode of passion'::text),'But that, O Arjuna, by which one holds fast to Dharma (duty), enjoyment of pleasures, and earning of wealth, on account of attachment and desire for reward—that firmness, O Arjuna, is Rajasic (passionate).','Swami Sivananda','18.34 यया (by) which? तु but? धर्मकामार्थान् Dharma (duty)? desire and wealth? धृत्या by firmness? धारयते holds? अर्जुन O Arjuna? प्रसङ्गेन on account of attachment? फलाकाङ्क्षी desirous of the fruit of action? धृतिः firmness? सा that? पार्थ O Arjuna? राजसी Rajasic (passionate).Commentary The man of Rajasic firmness imagines that he will achieve the threefold aim of life and clings to it passionately. He is desirous of getting the rewards of his actions. He endeavours to attain Dharma? wealth and pleasure. The firmness of such a person is Rajasic or passionate.Now listen? O Arjuna? to the third kind of firmness -- the Tamasic type.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',35,658,'18-35','यया स्वप्नं भयं शोकं विषादं मदमेव च।न विमुञ्चति दुर्मेधा धृतिः सा पार्थ तामसी।।18.35।।','yayā svapnaṁ bhayaṁ śhokaṁ viṣhādaṁ madam eva cha
na vimuñchati durmedhā dhṛitiḥ sā pārtha tāmasī',to_json('yayā—in which; svapnam—dreaming; bhayam—fearing; śhokam—grieving; viṣhādam—despair; madam—conceit; eva—indeed; cha—and; na—not; vimuñchati—give up; durmedhā—unintelligent; dhṛitiḥ—resolve; sā—that; pārtha—Arjun, the son of Pritha; tāmasī—in the mode of ignorance'::text),'That firmness, O Arjuna, by which a stupid man does not abandon sleep, fear, grief, despair, and conceit, is Tamasic.','Swami Sivananda','18.35 यया by which? स्वप्नम् sleep? भयम् fear? शोकम् grief? विषादम् despair? मदम् conceit? एव indeed? च and? न not? विमुञ्चति abandons? दुर्मेधाः a stupid man? धृतिः firmness? सा that? पार्थ O Arjuna? तामसी Tamasic (dark).Commentary The man who is an embodiment of darkness is made up of every possible kind of evil. He is very indolent and sinful. He is inordinately addicted to sleep. He considers these to be only proper. He experiences sorrow on account of his evil actions. As he is very much attached to the body he entertains great fear. He is ever discontented at heart. He is lustful and selfconceited. He does not know how to behave. He is rude and insolent. He indulges much in sensual pleasures.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',36,659,'18-36','सुखं त्विदानीं त्रिविधं श्रृणु मे भरतर्षभ।अभ्यासाद्रमते यत्र दुःखान्तं च निगच्छति।।18.36।।','sukhaṁ tv idānīṁ tri-vidhaṁ śhṛiṇu me bharatarṣhabha
abhyāsād ramate yatra duḥkhāntaṁ cha nigachchhati
 yat tad agre viṣham iva pariṇāme ‘mṛitopamam
tat sukhaṁ sāttvikaṁ proktam ātma-buddhi-prasāda-jam',to_json('sukham—happiness; tu—but; idānīm—now; tri-vidham—of three kinds; śhṛiṇu—hear; me—from me; bharata-ṛiṣhabha—Arjun, the best of the Bharatas; abhyāsāt—by practice; ramate—rejoices; yatra—in which; duḥkha-antam—end of all suffering; cha—and; nigachchhati—reaches
 yat—which; tat—that; agre—at first; viṣham iva—like poison; pariṇāme—in the end; amṛita-upamam—like nectar; tat—that; sukham—happiness; sāttvikam—in the mode of goodness; proktam—is said to be; ātma-buddhi—situated in self-knowledge; prasāda-jam—generated by the pure intellect'::text),'And now, O Arjuna, hear from Me of the threefold pleasure, in which one rejoices through practice and surely comes to the end of pain.','Swami Sivananda','18.36 सुखम् pleasure? तु indeed? इदानीम् now? त्रिविधम् threefold? श्रृणु hear? मे of Me? भरतर्षभ O lord of the Bharatas? अभ्यासात् from practice? रमते rejoices? यत्र in which? दुःखान्तम् the end of pain? च and? निगच्छति (he) attains to.Commentary A little of this pleasure experienced by the Self must result in the cessation of pain. This pleasure is threefold in its nature and I will describe its aspects in turn? O Arjuna. (Cf.VI.20?30).','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',37,660,'18-37','यत्तदग्रे विषमिव परिणामेऽमृतोपमम्।तत्सुखं सात्त्विकं प्रोक्तमात्मबुद्धिप्रसादजम्।।18.37।।','yat  tad agre    viṣam   iva pariṇāme    ''mṛtopamam  tat sukhaṁ  sāttvikaṁ   proktam ātma-buddhi-prasāda-jam',to_json('yat—that   which;  tat—that;   agre—in the beginning;  viṣam   iva—like    poison; pariṇāme—at the end;    amṛta—nectar;   upamam—compared to; tat—that;   sukham—happiness;   sāttvikam—in    the mode    of  goodness;   proktam—is   said;    ātma—self;    buddhi—intelligence;    prasāda-jam—satisfactory.'::text),'That which is like poison at first but in the end like nectar—that happiness is declared to be sattvic, born of the purity of one''s own mind due to self-realization.','Swami Sivananda','18.37 यत् which? तत् that? अग्रे at first? विषम् poison? इव like? परिणामे in the end? अमृतोपमम् like nectar? तत् that? सुखम् pleasure? सात्त्विकम् Sattvic? प्रोक्तम् is declared (to be)? आत्मबुद्धिप्रसादजम् born of the purity of ones own mind due to Selfrealisation.Commentary Agree vishma iva In the beginning it is attended with much pain as one has to abandon the sensual objects and comforts and practise severe austerities and rigorous Sadhana. He has to undergo a severe ordeal when he practises Yama? Niyama? Tapas and various other vows. He has to cultivate dispassion or indifference to sensual pleasures. This gives him much pain at first. The practice of concentration and meditation also gives pain the beginning. Subjugation of the senses is also very troublesome. Nux vomica is very bitter. One feels much discomfort when he takes a mixture that contains nux vomica. But he derives much pleasure in the end when he gets vigour and good appetite and when his dyspepsia is cured. Even so the aspirant drinks the nectar of immortality in the end? attains the highest knowledge? rejoices in the,Self to his hearts content and enjoys supreme peace and eternal bliss.Proktam It is declared by the wise.Atmabuddhiprasadajam Born as purity of ones own intellect or born of the direct? perfect and clear knowledge of Brahman or the immortal? selfluminous? eternal and supreme Self or the Absolute. The individual self experiences Sattvic happiness when it realises union with the highest Self.The pleasure so born is Sattvic. (Cf.VI.1?2)','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',38,661,'18-38','विषयेन्द्रियसंयोगाद्यत्तदग्रेऽमृतोपमम्।परिणामे विषमिव तत्सुखं राजसं स्मृतम्।।18.38।।','viṣhayendriya-sanyogād yat tad agre ’mṛitopamam
pariṇāme viṣham iva tat sukhaṁ rājasaṁ smṛitam',to_json('viṣhaya—with the sense objects; indriya—the senses; sanyogāt—from the contact; yat—which; tat—that; agre—at first; amṛita-upamam—like nectar; pariṇāme—at the end; viṣham iva—like poison; tat—that; sukham—happiness; rājasam—in the mode of passion; smṛitam—is said to be'::text),'That happiness which arises from the contact of the senses with the objects, which is initially like nectar but eventually like poison, is said to be Rajasic.','Swami Sivananda','18.38 विषयेन्द्रियसंयोगात् from the contact of the senseorgans with the objects? यत् which? तत् that? अग्रे at first? अमृतोपमम् like nectar? परिणामे in the end? विषम् poison? इव like? तत् that? सुखम् pleasure? राजसम् Rajasic? स्मृतम् is declared.Commentary Sensual pleasure is mixed with pain? fear and sin. A small grain of sensual pleasure is mixed with a mountain of pain. He who indulges in sensual pleasures will have to experience pain also? side by side. He is afraid of losing the objects that give him pleasure. He is attached to them. Attachment is death. It brings him again and again to this world of death. Fear and attachment coexist with sensual pleasure. He has to exert a lot to get money. He can obtain the objects through money. During exertion he commits many sinful acts and he will have to suffer in hell. The next birth will be of a very low nature. He tells lies and cheats people to obtain money. The senses also lose their vigour through indulgence in sensual pleasure. He loses his strength? vigour? wealth and energy. His intellect becomes dull? weak? impure? turbid and perverted. He loses his money and proper understanding. (Cf.V.22)','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',39,662,'18-39','यदग्रे चानुबन्धे च सुखं मोहनमात्मनः।निद्रालस्यप्रमादोत्थं तत्तामसमुदाहृतम्।।18.39।।','yad agre chānubandhe cha sukhaṁ mohanam ātmanaḥ
nidrālasya-pramādotthaṁ tat tāmasam udāhṛitam',to_json('yat—which; agre—from beginning; cha—and; anubandhe—to end; cha—and; sukham—happiness; mohanam—illusory; ātmanaḥ—of the self; nidrā—sleep; ālasya—indolence; pramāda—negligence; uttham—derived from; tat—that; tāmasam—in the mode of ignorance; udāhṛitam—is said to be'::text),'That happiness which at first, as well as in the end, deludes the self, and which arises from sleep, indolence, and heedlessness—that is declared to be Tamasic.','Swami Sivananda','18.39 यत् which? अग्रे at first? च and? अनुबन्धे in the seel? च and? सुखम् pleasure? मोहनम् delusive? आत्मनः of the self? निद्रालस्यप्रमादोत्थम् arising from sleep? indolence and heedlessness? तत् that? तामसम् Tamasic? उदाहृतम् is declared.Commentary Anubandhe In the conseence after the termination. The pleasure that is begotten by evil habits like drinking liors and eating worthless things is delusive of the self. The man becomes oblivious of the path he ought to tread. Such pleasure is verily of the nature of darkness.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',40,663,'18-40','न तदस्ति पृथिव्यां वा दिवि देवेषु वा पुनः।सत्त्वं प्रकृतिजैर्मुक्तं यदेभिः स्यात्ित्रभिर्गुणैः।।18.40।।','na tad asti pṛithivyāṁ vā divi deveṣhu vā punaḥ
sattvaṁ prakṛiti-jair muktaṁ yad ebhiḥ syāt tribhir guṇaiḥ',to_json('na—no; tat—that; asti—exists; pṛithivyām—on earth; vā—or; divi—the higher celestial abodes; deveṣhu—amongst the celestial gods; vā—or; punaḥ—again; sattvam—existence; prakṛiti-jaiḥ—born of material nature; muktam—liberated; yat—that; ebhiḥ—from the influence of these; syāt—is; tribhiḥ—three; guṇaiḥ—modes of material nature'::text),'There is no being on earth or in heaven among the gods that is liberated from the three qualities born of Nature.','Swami Sivananda','18.40 न not? तत् that? अस्ति is? पृथिव्याम् on the earth? वा or? दिवि in heaven? देवेषु among the gods? वा or? पुनः again? सत्त्वम् being? प्रकृतिजैः born of Prakriti (matter)? मुक्तम् freed? यत् which? एभिः from these? स्यात् may be? त्रिभिः from three? गुणैः by alities.Commentary The Gunas form the warp and woof of everything as threads do in the case of cloth.Here in the world of mortals or there in the heavenworld? there is no creature that is not bound by the three alities of Nature. Can there be a cloth without threads Can there be a man without blood and bones Can there be a mountain without stones Even so there is not a single creature in the whole universe into whose composition the three alities of matter do not enter. The whole of creation is wrought of these three alities. They have given rise to the Trinity (Brahma? Vishnu and Siva). In the world of mortals the triplicity of agent? action and fruit owe their origin to them. They are the cause of the different functions of the four castes. This Samsara has been compared to the peepul tree in chapter XV.1. This Samsara is made up of the three alities and is kept up by the force of ignorance.Action? instruments of action and fruits have set the wheel of Samsara in motion and this wheel is revolving from beginningless time. It is only a liberated sage who has attained knowledge of the Self who puts a check to this wheel? goes beyond the cause and the effect? and breaks the bonds of Karma.Cut this mysterious tree of Samsara with the strong sword of nonattachment? transcend the three Gunas and rest in your own essential divine nature as ExistenceKnowledgeBliss Absolute.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',41,664,'18-41','ब्राह्मणक्षत्रियविशां शूद्राणां च परंतप।कर्माणि प्रविभक्तानि स्वभावप्रभवैर्गुणैः।।18.41।।','brāhmaṇa-kṣhatriya-viśhāṁ śhūdrāṇāṁ cha parantapa
karmāṇi pravibhaktāni svabhāva-prabhavair guṇaiḥ',to_json('brāhmaṇa—of the priestly class; kṣhatriya—the warrior and administrative class; viśhām—the mercantile and farming class; śhūdrāṇām—of the worker class; cha—and; parantapa—Arjun, subduer of the enemies; karmāṇi—duties; pravibhaktāni—distributed; svabhāva-prabhavaiḥ-guṇaiḥ—work based on one’s nature and guṇas'::text),'Of Brahmanas, Kshatriyas, Vaisyas, and Sudras, O Arjuna, the duties are distributed according to the qualities born of their own nature.','Swami Sivananda','18.41 ब्राह्मणक्षत्रियविशाम् of Brahmanas? Kshatriyas and Vaisyas? शूद्राणाम् of Sudras? च as also? परंतप O Parantapa? कर्माणि duties? प्रविभक्तानि are distributed? स्वभावप्रभवैः born of their own nature? गुणैः by alities.Commentary Brahmanas? Kshatriyas and Vaisyas are alified to practise the Vedic rites. The members of the fourth class? O Arjuna? have no claim to these rites? for their profession is to serve the members of the first three. They are not allowed to study the Vedas or perform Yajnas. There is organisation of mankind into the four castes and each mans life is divided into four stages? according to the nature of the Gunas and the degree of the growth or evolution. I will now explain the specific duties of these castes according to the alities by means of which? freeing themselves from the grip of birth and death? they can attain Selfrealisation or knowledge of the Self. Passion (Rajas) slightly mingled with Tamas causes the growth of the merchant caste (the Vaisya). Rajas mixed with Tamas is the cause of the appearance of the Sudra.The one human race has been divided into four castes based upon the three alities. The duties are allotted to each according to the alities born of Nature.Nature (Svabhava) is Isvaras Prakriti (Maya) constituted of the three alities -- Sattva? Rajas and Tamas.The Brahmanas nature is Sattva. So he is serene. The nature of the Kshatriya is Rajas and Sattva. Sattva in his case is subordinate to Rajas. Rajas predominates. Therefore he possesses lordliness. The nature of the Vaisya is Rajas and Tamas. Tamas is subordinate to Rajas. So he does various sorts of activities or business to earn money. The nature of the Sudra is Tamas? with subordinate Rajas. He is dull.Karma is action arising from and fashioned by past thoughts and desires. The Gunas cannot manifest themselves without a cause. Nature is the tendency? Samskara or Vasana in living beings. This is acired by them in the past births. This manifests itself in the present birth and produces its effects. This nature is the source of the Gunas. Every man or woman is born with his or her own Svabhava (nature). The Gunas operate according to the respective natural tendencies of man which impel him to perform his own duties as their natural effects. The duties are allottted to the four classes or castes in accordance with the Gunas of individuals. (Cf.IV.13)','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',42,665,'18-42','शमो दमस्तपः शौचं क्षान्तिरार्जवमेव च।ज्ञानं विज्ञानमास्तिक्यं ब्रह्मकर्म स्वभावजम्।।18.42।।','śhamo damas tapaḥ śhauchaṁ kṣhāntir ārjavam eva cha
jñānaṁ vijñānam āstikyaṁ brahma-karma svabhāva-jam',to_json('śhamaḥ—tranquility; damaḥ—restraint; tapaḥ—austerity; śhaucham—purity; kṣhāntiḥ—patience; ārjavam—integrity; eva—certainly; cha—and; jñānam—knowledge; vijñānam—wisdom; āstikyam—belief in a hereafter; brahma—of the priestly class; karma—work; svabhāva-jam—born of one’s intrinsic qualities'::text),'Serenity, self-restraint, austerity, purity, forgiveness, and uprightness, as well as knowledge, realization, and belief in God, are the duties of Brahmanas, born of their own nature.','Swami Sivananda','18.42 शमः serenity? दमः selfrestraint? तपः austerity? शौचम् purity? क्षान्तिः forgiveness? आर्जवम् uprightness? एव even? च and? ज्ञानम् knowledge? विज्ञानम् realisation? आस्तिक्यम् belief in God? ब्रह्मकर्म (are) the duties of Brahmanas? स्वभावजम् born of nature.Commentary Sama is control of the mind. Dama is control of the senses. Serenity and selfrestraint have already been explained in XVII.2. Austerity of the three kinds has also been explained in XVII.14 to 16.Astikyam Faith in the words of the Guru? in the teachings of the scriptures? in the existence of God? in the life beyond or hereafter and in ones own Self.The mind is absorbed in the Self. This gives peace. Selfrestraint is the helpmate of peace. In obeying the inunctions of the scriptures alone you will attain peace and spiritual progress. You must not argue too much. You must have reverence for and faith in the teaching.As the sandalwood tree is fragrant with its own sweet scent? as a Champaka tree is adorned by its lovely flowers? so also a Brahmana is adorned by these nine virtues which are inseparable from him.Now? O Arjuna? listen to the duties of a Kshatriya.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',43,666,'18-43','शौर्यं तेजो धृतिर्दाक्ष्यं युद्धे चाप्यपलायनम्।दानमीश्वरभावश्च क्षात्रं कर्म स्वभावजम्।।18.43।।','śhauryaṁ tejo dhṛitir dākṣhyaṁ yuddhe chāpy apalāyanam
dānam īśhvara-bhāvaśh cha kṣhātraṁ karma svabhāva-jam',to_json('śhauryam—valor; tejaḥ—strength; dhṛitiḥ—fortitude; dākṣhyam yuddhe—skill in weaponry; cha—and; api—also; apalāyanam—not fleeing; dānam—large-heartedness; īśhvara—leadership; bhāvaḥ—qualities; cha—and; kṣhātram—of the warrior and administrative class; karma—work; svabhāva-jam—born of one’s intrinsic qualities'::text),'Prowess, splendor, firmness, dexterity, and not fleeing from battle, generosity, and lordliness are the duties of the Kshatriyas, born of their own nature.','Swami Sivananda','18.43 शौर्यम् prowess? तेजः splendour? धृतः firmness? दाक्ष्यम् dexterity? युद्धे in battle? च and? अपि also? अपलायनम् not fleeing? दानम् generosity? ईश्वरभावः lordliness? च and? क्षात्रम् of Kshatriyas? कर्म action? स्वभावजम् born of nature.Commentary It is the first duty of Kshatriya (man of the warrior class or of royal blood) to be brave and chivalrous. Bravery is that sublime virtue through which one is naturally strong? vigorous and courageous. In the face of the most terrible calamity the mind will not be in the least perturbed. The Kshatriya is firm under any unfavourable or trying conditions or circumstances. He does not get the least depression of spirit even when he is in adverse circumstances. It is the skill by which the reason finds out its path amidst all untoward circumstances and eventually attains its goal. This is firmness? fortitude or courage.Dakshya Promptness He is able to decide rightly on the spot in matters that deman prompt attention doing without confusion? of duties which present themselves all of a sudden and demand prompt action.As the sunflower always turns its face towards the sun so does he always face his enemies. He will ever avoid turning his back to them on the field of battle. He is absolutely fearless. Just as a tree gives away its flowers and fruits freely to whoever desires them? as the jasmine sends out its sweet fragrace in every direction? so will a Kshatriya generously give to another whatever may be asked of him. His charity is boundless.Lordliness A Kshatriya king enjoys sovereignty over his subjects owing to the sure protection he grants them? exercises ruling power over his subjects who are to be ruled? and raises the rod of chastisement to punish the unrighteous or the wicked.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',44,667,'18-44','कृषिगौरक्ष्यवाणिज्यं वैश्यकर्म स्वभावजम्।परिचर्यात्मकं कर्म शूद्रस्यापि स्वभावजम्।।18.44।।','kṛiṣhi-gau-rakṣhya-vāṇijyaṁ vaiśhya-karma svabhāva-jam
paricharyātmakaṁ karma śhūdrasyāpi svabhāva-jam',to_json('kṛiṣhi—agriculture; gau-rakṣhya—dairy farming; vāṇijyam—commerce; vaiśhya—of the mercantile and farming class; karma—work; svabhāva-jam—born of one’s intrinsic qualities; paricharyā—serving through work; ātmakam—natural; karma—duty; śhūdrasya—of the worker class; api—and; svabhāva-jam—born of one’s intrinsic qualities'::text),'Agriculture, cattle-rearing, and trade are the duties of the Vaisya (merchant), born of their own nature; and service is the duty of the Sudra (servant-class), born of their own nature.','Swami Sivananda','18.44 कृषिगौरक्ष्यवाणिज्यम् agriculture? cattlerearing and trade? वैश्यकर्म the duties of Vaisya? स्वभावजम् born of nature? परिचर्यात्मकम् consisting of service? कर्म action? शूद्रस्य of the Sudra? अपि also? स्वभावजम् born of nature.Commentary When a man performs his duties rightly according to his caste and order of life his heart is purified and he goes to heaven. Apastambha Dharma Sutra declares? Men of severla,castes and orders? each devoted to his respective duties? reap the fruits of their actions after death? and then by the residual Karma attain to births in superior Dharma? span of life? learning? conduct? wealth? happiness and intelligence (2?2?2?3). There is a vivid description in the Puranas also of the different results and worlds which men of the four castes and orders obtain by discharging their respective duties.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',45,668,'18-45','स्वे स्वे कर्मण्यभिरतः संसिद्धिं लभते नरः।स्वकर्मनिरतः सिद्धिं यथा विन्दति तच्छृणु।।18.45।।','sve sve karmaṇy abhirataḥ sansiddhiṁ labhate naraḥ
sva-karma-nirataḥ siddhiṁ yathā vindati tach chhṛiṇu',to_json('sve sve—respectively; karmaṇi—work; abhirataḥ—fulfilling; sansiddhim—perfection; labhate—achieve; naraḥ—a person; sva-karma—to one’s own prescribed duty; nirataḥ—engaged; siddhim—perfection; yathā—as; vindati—attains; tat—that; śhṛiṇu—hear'::text),'Each person devoted to their own duty attains perfection. How they attain perfection while being engaged in their own duty, hear now.','Swami Sivananda','18.45 स्वे in own? स्वे in own? कर्मणि to duty? अभिरतः devoted? संसिद्धिम् perfection? लभते attains? नरः a man? स्वकर्मनिरतः engaged in his own duty? सिद्धिम् perfection? यथा how? विन्दति finds? तत् that? श्रृणु hear.Commentary This is the division of labour for which each caste is fitted according to its own nature. The duty prescribed is your sole support? and the highest service you can render to the Supreme is to carry it out wholeheartedly? without expectation of fruits? with the attitutde of dedication to the Lord. This will surely lead you to the Supreme. All the impurities of the mind will be washed away by the performance of ones own duty and you will be fit for Selfknowledge.Sve sve karmani Each devoted to his own duty in accordance with his nature (Guna) or caste. It is impossible to attain Moksha by works alone but works purify the heart and prepare the aspirant for receiving the divine light.The attitude of worshipfulness is prescribed for work','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',46,669,'18-46','यतः प्रवृत्तिर्भूतानां येन सर्वमिदं ततम्।स्वकर्मणा तमभ्यर्च्य सिद्धिं विन्दति मानवः।।18.46।।','yataḥ pravṛittir bhūtānāṁ yena sarvam idaṁ tatam
sva-karmaṇā tam abhyarchya siddhiṁ vindati mānavaḥ',to_json('yataḥ—from whom; pravṛittiḥ—have come into being; bhūtānām—of all living entities; yena—by whom; sarvam—all; idam—this; tatam—pervaded; sva-karmaṇā—by one’s natural occupation; tam—him; abhyarchya—by worshipping; siddhim—perfection; vindati—attains; mānavaḥ—a person'::text),'He from whom all the beings have evolved and by whom all this is pervaded, worshipping Him with his own duty, one attains perfection.','Swami Sivananda','18.46 यतः from whom? प्रवृत्तिः (is) the evolution? भूतानाम् of beings? येन by whom? सर्वम् all? इदम् this? ततम् is pervaded? स्वकर्मणा with his own duty? तम् Him? अभ्यर्च्य worshipping? सिद्धिम् perfection? विन्दति attains? मानवः man.Commentary The performance by a man of his own duty is simply carrying into effect the intention of the Supreme from Whom the whole of the creation emanates. When a man worships Him? the Supreme Being? with the flowers of his action? then He is immensely pleased and being thus gratified by such worship He confers on Him? as a boon? dispassion and discrimination.Pravritti Evolution or activity it proceeds from the Lord? the Antaryamin? the Inner Ruler.Bhutanam Beings living creatures.Svakarmana With his own duty each according to his caste as described above.Man attains perfection by worshipping the Lord by performing his own duty? i.e.? he becomes alified for the dawn of Selfknowledge (for Jnana Yoga).','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',47,670,'18-47','श्रेयान्स्वधर्मो विगुणः परधर्मात्स्वनुष्ठितात्।स्वभावनियतं कर्म कुर्वन्नाप्नोति किल्बिषम्।।18.47।।','śhreyān swa-dharmo viguṇaḥ para-dharmāt sv-anuṣhṭhitāt
svabhāva-niyataṁ karma kurvan nāpnoti kilbiṣham',to_json('śhreyān—better; swa-dharmaḥ—one’s own prescribed occupational duty; viguṇaḥ—imperfectly done; para-dharmāt—than another’s dharma; su-anuṣhṭhitāt—perfectly done; svabhāva-niyatam—according to one’s innate nature; karma—duty; kurvan—by performing; na āpnoti—does not incur; kilbiṣham—sin'::text),'Better is one''s own duty, even if it is destitute of merits, than the duty of another well performed. He who does the duty ordained by his own nature incurs no sin.','Swami Sivananda','18.47 श्रेयान् better? स्वधर्मः ones own duty? विगुणः (though) destitute of merits? परधर्मात् that the duty of another? स्वनुष्ठितात् (than) well performed? स्वभावनियतम् ordained by his own nature? कर्म action? कुर्वन् doing? न not? आप्नोति (he) incurs? किल्बिषम् sin.Commentary Just as a poisonous substance does not harm the worm born in that substance? so he who does his Svadharma (the duty ordained according to his own nature) does not incur any sin.What is poison to the whole world is sweet to a worm and yet sugarcane juice that is sweet causes its death. So a mans appointed duty which frees him from bondage must? therefore? be practised however difficult it may seem to be. If you try to do the duty of another it will bring,danger. He who has no knowledge of the Self cannot remain even for a moment without doing action. (Cf.III.35)','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',48,671,'18-48','सहजं कर्म कौन्तेय सदोषमपि न त्यजेत्।सर्वारम्भा हि दोषेण धूमेनाग्निरिवावृताः।।18.48।।','saha-jaṁ karma kaunteya sa-doṣham api na tyajet
sarvārambhā hi doṣheṇa dhūmenāgnir ivāvṛitāḥ',to_json('saha-jam—born of one’s nature; karma—duty; kaunteya—Arjun, the son of Kunti; sa-doṣham—with defects; api—even if; na tyajet—one should not abandon; sarva-ārambhāḥ—all endeavors; hi—indeed; doṣheṇa—with evil; dhūmena—with smoke; agniḥ—fire; iva—as; āvṛitāḥ—veiled'::text),'One should not, O Arjuna, abandon the duty to which one is born, though it may be faulty; for, all undertakings are enveloped by evil, just as fire is by smoke.','Swami Sivananda','18.48 सहजम् which is born? कर्म action? कौन्तेय O Kaunteya? सदोषम् with fault? अपि even? न not? त्यजेत् (one) should abandon? सर्वारम्भाः all undertakings? हि for? दोषेण by evil? धूमेन by smoke? अग्निः fire? इव like? आवृताः are enveloped.Commentary Sahajam Born with oneself born with the birth of man.Sadosham Faculty for everything is constituted of the three Gunas.All undertakings Ones own as well as others duties.If a Vaisya or a Kshatriya does the duties of a Brahmana he will not in any way be benefited. Anothers duty brings in fear. Therefore it is not proper to perform anothers duty. It is not possible for any man who has no knowledge of the Self to relinish action totally therefore he should not abandon action.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',49,672,'18-49','असक्तबुद्धिः सर्वत्र जितात्मा विगतस्पृहः।नैष्कर्म्यसिद्धिं परमां संन्यासेनाधिगच्छति।।18.49।।','asakta-buddhiḥ sarvatra jitātmā vigata-spṛihaḥ
naiṣhkarmya-siddhiṁ paramāṁ sannyāsenādhigachchhati',to_json('asakta-buddhiḥ—those whose intellect is unattached; sarvatra—everywhere; jita-ātmā—who have mastered their mind; vigata-spṛihaḥ—free from desires; naiṣhkarmya-siddhim—state of actionlessness; paramām—highest; sanyāsena—by the practice of renunciation; adhigachchhati—attain'::text),'He whose intellect is unattached everywhere, who has subdued his self, from whom desire has fled, he attains the supreme state of freedom from action through renunciation.','Swami Sivananda','18.49 असक्तबुद्धिः whose intellect is unattached? सर्वत्र eveywhere? जितात्मा who has subdued his self? विगतस्पृहः whose desire has fled? नैष्कर्म्यसिद्धिम् the perfection consisting in freedom from action? परमाम् the supreme? संन्यासेन by renunciaion? अधिगच्छति (he) attains.Commentary The mind of one who is free from attachment to wife? son? body and property? who has controlled his senses and the mind? who has no desire for the body? for life and for sensual pleasure? turns inwards towards God or the immortal Self. It is not attracted by the sensual objects of the world. It is filled with dispassion and discrimination.He gradually gets himself established in his own Self which is of the nature of ExistenceKnowledgeBliss. Such a person who has knowledge of the Self attains to the highest perfection? to pefect freedom from action by renunciation.Ignorance is destroyed by the attainment of the knowledge of the Self. There is cessation of activity. One may perform actions for the solidarity of the world and yet he will not be bound by actions as he has attained absolute freedom from action through the knowledge of the Self. The fire of knowledge has burnt the fruitbearing effects of Karmas or actions. He has no idea of agency as he is absolutely free from egoism? as he has identified himself with the Supreme Being.Naishkarmya siddhi may also mean the attainment of the state of Naishkarmya. In this exalted? magnanimous? ineffable state of divine splendour and glory? one remains as the actionless Self. This is the state of immediate liberation of the Vedantins (Kaivalya Moksha or Sadyomukti). This marvellous state is attained by renunciation or right knowledge or by the renunciation of all actions brought about by the attainment of the knowledge of the Self. Mentally renouncing all actions and selfcontrolled? the embodied one rests happily in the ninegated? city? neither acting nor causing others to act. (Cf.V.13)Now the Lord teaches in the next verse how a man who? having attained perfection as described above in verse 46? by doing his duty in the service of the Lord can attain perfect freedom from action. He gets discrimination? practises constant meditation and rests in the knowledge of the immutable Self.,(Cf.III.4and19)','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',50,673,'18-50','सिद्धिं प्राप्तो यथा ब्रह्म तथाप्नोति निबोध मे।समासेनैव कौन्तेय निष्ठा ज्ञानस्य या परा।।18.50।।','siddhiṁ prāpto yathā brahma tathāpnoti nibodha me
samāsenaiva kaunteya niṣhṭhā jñānasya yā parā',to_json('siddhim—perfection; prāptaḥ—attained; yathā—how; brahma—Brahman; tathā—also; āpnoti—attain; nibodha—hear; me—from me; samāsena—briefly; eva—indeed; kaunteya—Arjun, the son of Kunti; niṣhṭhā—firmly fixed; jñānasya—of knowledge; yā—which; parā—transcendental'::text),'Learn from Me, O Arjuna, in brief how one who has attained perfection reaches Brahman—the Eternal, that supreme state of knowledge.','Swami Sivananda','18.50 सिद्धिम् perfection? प्राप्तः attained? यथा as? ब्रह्म Brahman (the Eternal)? तथा so? आप्नोति obtains? निबोध learn? मे of Me? समासेन in brief? एव even? कौन्तेय O son of Kunti? निष्ठा state? ज्ञानस्य of knowledge? या or? परा highest.Commentary When a man has the good fortune to hear the words of wisdom from a teacher? dualism and egoism vanish and his mind rests in union with the Supreme Being. The need for action no longer exists for such a man. Nothing further remains for him to do. He has become a Kritakritya (a man of total fulfilment? or one who has done all that there is to be done).The aspirant obtains the grace of the Lord by worshipping Hims with his proper duty. The Lord gives him dispassion? discrimination? devotion to knowledge. The Lord removes his veil of ignorance. To these ever harmonious? worshipping in love? I give the Yoga of discrimination by which they come unto Me. Out of My mere compassion for them? I? dwelling within their Self? destroy the darkness born of ignorance by the luminous lamp of knowledge. (X.10and11)The perfection is JnanaNishtha or devotion to knowledge by which he attains Selfrealisation or becomes identical with the Supreme Being when the veil of ignorance is rent asunder. The way to the attainment of this devotion to knowledge will be described only in a succint manner. The process or method of Selfrealisation will be described only in brief in the following verses.The actual technie has to be learnt direct from a Guna.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',51,674,'18-51','बुद्ध्या विशुद्धया युक्तो धृत्याऽऽत्मानं नियम्य च।शब्दादीन् विषयांस्त्यक्त्वा रागद्वेषौ व्युदस्य च।।18.51।।','buddhyā viśhuddhayā yukto dhṛityātmānaṁ niyamya cha
śhabdādīn viṣhayāns tyaktvā rāga-dveṣhau vyudasya cha',to_json('buddhyā—intellect; viśhuddhayā—purified; yuktaḥ—endowed with; dhṛityā—by determination; ātmānam—the intellect; niyamya—restraining; cha—and; śhabda-ādīn viṣhayān—sound and other objects of the senses; tyaktvā—abandoning; rāga-dveṣhau—attachment and aversion; vyudasya—casting aside; cha—and;'::text),'Endowed with a pure intellect, controlling the self through firmness, relinquishing sound and other objects and abandoning attraction and hatred.','Swami Sivananda','18.51 बुद्ध्या with an intellect? विशुद्धया pure? युक्तः endowed? धृत्या by firmness? आत्मानम् the self? नियम्य controlling? च and? शब्दादीन् sound and other? विषयान् senseobjects? त्यक्त्वा relinishing? रागद्वेषौ attraction and hatred? व्युदस्य abandoning? च and.Commentary The lower self should be controlled with firmness by the Self of pure intellect. The turbulent senses and the mind should be subdued with the help of the pure intellect or reason. Pure reason is a great power. Whenever the senses raise their heads and hiss? they should be hammered by the powerful rod of pure intellect or reason. Reason is the faculty of determination.Pure intellect The intellect that is free from lust? anger? greed? pride? doubt? misconception? etc. It is like a clear mirror. A pure intellect is Brahman Itself. It can be easily merged in Brahman. When the pure intellect is merged in Brahman? the reflected intelligence? Chidabhasa or Jiva? is also absorbed in Brahman. The Jiva becomes identical with Brahman? just as the ether in the pot becomes one with the universal ether when the pot is broken.The self The aggregate of the body and the senses.The aspirant withdraws the senses from their respective objects again and again through the repeated practice of Pratyahara (abstraction) and Dama (selfrestraint). Gradually the senses are fixed in the Self. Their outgoing tendencies are totally curbed. The aspirant attains supreme control of the senses by constant meditation? by the practice of dispassion he coners Raga (attachment)? and through the practice of pure love or cosmic love or divine Preme he coners hatred.He abandons all luxuries. He keeps only those objects which are necessary for the bare maintenance of the body. He has neither attachment nor hatred even for those objects which are necessary for that purpose.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',52,675,'18-52','विविक्तसेवी लघ्वाशी यतवाक्कायमानसः।ध्यानयोगपरो नित्यं वैराग्यं समुपाश्रितः।।18.52।।','vivikta-sevī laghv-āśhī yata-vāk-kāya-mānasaḥ
dhyāna-yoga-paro nityaṁ vairāgyaṁ samupāśhritaḥ',to_json('vivikta-sevī—relishing solitude; laghu-āśhī—eating light; yata—controls; vāk—speech; kāya—body; mānasaḥ—and mind; dhyāna-yoga-paraḥ—engaged in meditation; nityam—always; vairāgyam—dispassion; samupāśhritaḥ—having taken shelter of;'::text),'Dwelling in solitude, eating sparingly, with speech, body, and mind subdued, always engaged in meditation and concentration, and resorting to dispassion.','Swami Sivananda','18.52 विविक्तसेवी dwelling in solitude? लघ्वाशी eating but little? यतवाक्कायमानसः speech? body and mind subdued? ध्यानयोगपरः engaged in meditation and concentration? नित्यम् always? वैराग्यम् dispassion? समुपाश्रितः resorting to.Commentary Solitude has its own charms. The spiritual vibrations in solitude are wonderfully elevating. Meditation will come by itself without exertion. All saints and sages who have attained Selfrealisation have remained in solitude for a number of years. You will have good meditation if you sit on the bank of a river? in a cave or on the seashore or in a jungle. During the Christmas and Easter holidays you can all enjoy the peace of solitude. It is very necessary to live in solitude at least for a month or a fortnight in a year for the householders. Instead of wasting time? energy and money in Calcutta or any other city? during the holidays? live in holy places like Rishikesh? Uttarakasi or Naimisaranya drink the nectar of peace in such places by doing Anushthana (intense and systematic spiritual practice) or Japa of a Mantra and attain immortality. If you once taste the bliss of solitude you will never forget it. Every year you will attempt to taste it again. He who takes too much food (a glutton) is ite unfit for meditation or the spiritual path. Too much food will produce laziness? a halfsleepy state and deep sleep also. Eat to live. Eat in moderation. You will have a light body and light? cheerful and serene mind. This will help you in your practice of meditation. Observe Mauna or the vow of silelnce for a week or a month. Observe the vow for two hours daily. Control the body. Practise Ahimsa and Brahmacharya. Meditate on the Self or on the Lord Hari with four hands? or on Lord Krishna? Rama or Siva. Be regular in your meditation and gradually increase the period of meditation from 15 minutes to 3 or 6 hours at a sitting. If you are a wholetimed aspirant? spend the whole time in meditation. If you are not able to do this? do Likhita Japa (writing the Mantra) and Kirtan (singing the Names and glories of the Lord). Study religious books in the interval. Only advanced aspirants can meditate for a long time. Watch the mind and cultivate dispassion. Energy will leak out through the senses if you are careless and nonvigilant. If energy leaks out? you cannot have good meditation. Dispassion is indifference to sensual enjoyments herein and hereafter? absence of desire for visible and invisible objects. You must have steady? lasting and sustained dispassion. It should not wane. It should be a constant attitude of the mind. You must be fully established in dispassion.In doing the Anushthana for 40 days live on milk and fruits or light diet. Take only 3 or 4 articles of food. Take one meal only. Sleep on the floor. Observe celibacy and the vow of silence. Do not come out of the room. Speak little if you do not observe perfect silence. Do the Anushthana on the banks of the Ganga or any sacred river. Try to do one or several Purascharanas of your Ishta Mantra. If there are five letters (syllables in English) in the Mantra? 500?000 repetitions of the Mantra will constitute one Purascharana.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',53,676,'18-53','अहङ्कारं बलं दर्पं कामं क्रोधं परिग्रहम्।विमुच्य निर्ममः शान्तो ब्रह्मभूयाय कल्पते।।18.53।।','ahankāraṁ balaṁ darpaṁ kāmaṁ krodhaṁ parigraham
vimuchya nirmamaḥ śhānto brahma-bhūyāya kalpate',to_json('ahankāram—egotism; balam—violence; darpam—arrogance; kāmam—desire; krodham—anger; parigraham—selfishness; vimuchya—being freed from; nirmamaḥ—without possessiveness of property; śhāntaḥ—peaceful; brahma-bhūyāya—union with Brahman; kalpate—is fit'::text),'Having abandoned egoism, strength, arrogance, desire, anger, and covetousness, and being free from the notion of ''mine'' and peaceful, he is fit for becoming Brahman.','Swami Sivananda','18.53 अहङ्कारम् egoism? बलम् strength? दर्पम् arrogance? कामम् desire? क्रोधम् anger? परिग्रहम् covetousness? विमुच्य having abandoned? निर्ममः without mineness? शान्तः peaceful? ब्रह्मभूयाय for becoming Brahman? कल्पते (he) is fit.Commentary Egoism Identifying the Self with the body? etc. This is the error of mistaking the physical body for the pure immortal Self.Balam That strength which is combined or united with passion? desire and attachment? and not the physical or other strength. Physical strength is natural. It is not possible to abandon this physical strength.Darpam Arrogance? insolence? selfassertive Rajasic vehemence this follows the state of exaltion.,Man becomes arrogant when he possesses wealth or much learning. When he becomes arrogant he violates Dharma and does wicked deeds.The aspirant even abandons the things which are necessary for the bare maintenance of the body. He becomes a ParamahamsaParivrajaka? a wandering or itinerant ascetic. He has no attachment to his body. He knows that even the body does not belong to him.Santa Peaceful? tranil? serene.Such an aspirant who has devotion to Selfknowledge? and who is endowed with the above virtues is fit to become Brahman.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',54,677,'18-54','ब्रह्मभूतः प्रसन्नात्मा न शोचति न काङ्क्षति।समः सर्वेषु भूतेषु मद्भक्तिं लभते पराम्।।18.54।।','brahma-bhūtaḥ prasannātmā na śhochati na kāṅkṣhati
samaḥ sarveṣhu bhūteṣhu mad-bhaktiṁ labhate parām',to_json('brahma-bhūtaḥ—one situated in Brahman; prasanna-ātmā—mentally serene; na—neither; śhochati—grieving; na—nor; kāṅkṣhati—desiring; samaḥ—equitably disposed; sarveṣhu—toward all; bhūteṣhu—living beings; mat-bhaktim—devotion to me; labhate—attains; parām—supreme'::text),'Becoming Brahman, serene in the Self, he neither grieves nor desires; he is the same to all beings, and obtains supreme devotion to Me.','Swami Sivananda','18.54 ब्रह्मभूतः having become Brahman? प्रसन्नात्मा sereneminded? न not? शोचति (he) grieves? न not? काङ्क्षति desires? समः the same? सर्वेषु all? भूतेषु in beings? मद्भक्तिम् devotion unto Me? लभते obtains? पराम् supreme.Commentary Brahmabhutah Having attained to Brahman. His attainment of perfect freedom or oneness with the Supreme is described in the next verse.He is tranilminded. He is in a state of balance and eanimity. There is nothing connected with the little personality that may cause him to grieve or prompt him to feel desire. When this state is attained? the multiplicity of objects gradually disappears and he perceives only unity everywhere. The waking and dream consciousness that gives rise to false knowledge gradually passes away.He does not grieve about his bodily wants. If he fails in his attempt to fulfil them? he does not grieve either. He always keeps evenness of mind in success and failure. He has no longing for any object that is not attained.Na sochati na kankshati can also be interpreted as he neither grieves nor exults.Samah sarveshu bhuteshu may also mean he puts himself in the position of others and feels for others. If anyone is in acute agony or distress? he himself feels that he is affected. His heart is very tender and soft. He is extremely compassionate and merciful. He considers that the pleasure and pain of all beings are his own. If others rejoice he also rejoices if others are in distress? he also is distressed. His heart is so much expanded that he feels for all. Jealousy? narrowness of heart? pettymindedness? the idea of separateness? all barriers that separate man from man? prejudices of all sorts and dislike for others -- all vanished in toto. He has cosmic love. He is a cosmic benefactor. He is the friend of all. This state of expansion is beyond description. One has to experience it for oneself. Such a devotee or aspirant attains supreme devotion to Me? the fourth or the highest of the four kinds of devotion mentioned in verse 16 of chapter VII? viz.? devotion of knowledge of the man of wisdom. (Cf.II.70)','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',55,678,'18-55','भक्त्या मामभिजानाति यावान्यश्चास्मि तत्त्वतः।ततो मां तत्त्वतो ज्ञात्वा विशते तदनन्तरम्।।18.55।।','bhaktyā mām abhijānāti yāvān yaśh chāsmi tattvataḥ
tato māṁ tattvato jñātvā viśhate tad-anantaram',to_json('bhaktyā—by loving devotion; mām—me; abhijānāti—one comes to know; yāvān—as much as; yaḥ cha asmi—as I am; tattvataḥ—in truth; tataḥ—then; mām—me; tattvataḥ—in truth; jñātvā—having known; viśhate—enters; tat-anantaram—thereafter'::text),'By devotion, he knows Me in truth, who and what I am; then, having known Me in truth, he immediately enters into the Supreme.','Swami Sivananda','18.55 भक्त्या by devotion? माम् Me? अभिजानाति (he) knows? यावान् what? यः who? च and? अस्मि (I) am? तत्त्वतः in truth? ततः then? माम् Me? तत्त्वतः in truth? ज्ञात्वा having known? विशते (he) enters? तत् that? अनन्तरम् afterwards.Commentary My devotee? O Arjuna? who has attained to union with Me through singleminded and unflinching devotion is verily My very Self. Devotion culminates in knowledge. Devotion begins with two and ends in one. ParaBhakti (supreme devotion) and Jnana are one. Devotion is the mother. Knowledge is the son. By devotion he knows that I am allpervading pure,consciousness he knows that I am nondual? unborn? decayless? causeless? selfluminous? indivisible? unchanging he knows that I am destitute of all the differences caused by the limiting adjuncts he knows that I am the support? source? womb? basis? and substratum of everything he knows that I am the ruler of all beings he knows that I am the Supreme Purusha? the controller of Maya? and that this world is a mere appearance. Thus knowing Me in truth or in essence? he enters into Me soon after attaining Selfknowledge.The act of knowing and the act of entering are not two distinct acts. Knowing is becoming. Knowing is attaining Selfknowledge. To know That is to become That. Entering is knowing or beoming That. Entering is the attainment of Selfknowledge or Selfrealisation. These are all jugglery of words only. Knowing and entering are synonymous terms. It is very difficult to understand or comprehend transcendental spiritual matters. The teachers use various terms or expressions? analogies? similes? parables? stories? etc. to make the aspirant grasp the matter clearly and lucidly. Words are imperfect and languages are defective. They cannot fully express the inner spiritual experiences. The teacher somehow or other expresses to the students or aspirants these spiritual ideas. The aspirant himself will have to realise the Self. That is beyond the reach of words of expressions or analogies of similes. How can there be similes for that nondual Brahman These words are a sort of help or prop for the aspirants to lean upon in the beginning to understand spiritual matters. When he realises the Self? these words are of no value to him. He himself becomes an embodiment of knowledge.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',56,679,'18-56','सर्वकर्माण्यपि सदा कुर्वाणो मद्व्यपाश्रयः।मत्प्रसादादवाप्नोति शाश्वतं पदमव्ययम्।।18.56।।','sarva-karmāṇy api sadā kurvāṇo mad-vyapāśhrayaḥ
mat-prasādād avāpnoti śhāśhvataṁ padam avyayam',to_json('sarva—all; karmāṇi—actions; api—though; sadā—always; kurvāṇaḥ—performing; mat-vyapāśhrayaḥ—take full refuge in me; mat-prasādāt—by my grace; avāpnoti—attain; śhāśhvatam—the eternal; padam—abode; avyayam—imperishable'::text),'Having taken refuge in Me and doing all actions, by My grace he obtains the eternal, indestructible state of being.','Swami Sivananda','18.56 सर्वकर्माणि all actions? अपि also? सदा always? कुर्वाणः doing? मद्व्यपाश्रयः taking refuge in Me? मत्प्रसादात् by My grace? अवाप्नोति obtains? शाश्वतम् the eternal? पदम् state or abode? अव्ययम् indestructible.Commentary Worshipping Me with the flowers of his good actions he reaches the imperishable Brahmic seat of ineffable splendour through My grace. He attains union with Me and enjoys the supreme bliss. If by chance he commits some prohibited actions? still? as in the Ganga (Indias most holy river) the waters of the drains and roads find union? so My devotee? becoming united with Me? is unaffected by these prohibited actions.Worship of the Lord through ones duties purifies the heart of the aspirant and prepares him for the devotion to knowledge which eventually leads him to the attainment of Selfrealisation. The Yoga of Devotion is eulogised here.All actions Good actions and even the prohibited actions. He who takes shelter in Me? Vaasudeva? the Lord? with his whole self centred in Me attains the eternal abode of Vishnu? by the grace of the Lord.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',57,680,'18-57','चेतसा सर्वकर्माणि मयि संन्यस्य मत्परः।बुद्धियोगमुपाश्रित्य मच्चित्तः सततं भव।।18.57।।','chetasā sarva-karmāṇi mayi sannyasya mat-paraḥ
buddhi-yogam upāśhritya mach-chittaḥ satataṁ bhava',to_json('chetasā—by consciousness; sarva-karmāṇi—every activity; mayi—to me; sannyasya—dedicating; mat-paraḥ—having me as the supreme goal; buddhi-yogam—having the intellect united with God; upāśhritya—taking shelter of; mat-chittaḥ—consciousness absorbed in me; satatam—always; bhava—be'::text),'Mentally renouncing all actions in Me, having Me as the highest goal, and resorting to the yoga of discrimination, do thou ever fix thy mind on Me.','Swami Sivananda','18.57 चेतसा mentally? सर्वकर्माणि all actions? मयि in Me? संन्यस्य resigning? मत्परः having Me as the highest goal? बुद्धियोगम् the Yoga of discrimination? उपाश्रित्य resorting to? मच्चित्तः with the mind fixed on Me? सततम् always? भव be.Commentary Do thou? O Arjuna? surrender all thy actions to Me whilst at the same time fixing thy mind on discrimination. Then through that discrimination thou wilt see thy Self as separate from the body and activity and existing in My pure Being.    Chetasa Mentally with the discriminative faith that knowledge finally leads to liberation when the heart is purified through selfless works done with the spirit of offering to God.Sarvakarmani All actions producing visible and invisible results.Me The Lord As taught in verse 27 of chapter IX Whatever thou doest? whatever thou eatest? etc.? do thou dedicate all thy actions to Me.Matparah Taking Me? Vaasudeva? as the supreme goal? and his whole self centred in Me.Resorting to Buddhi Yoga As thy sole refuge steadymindedness.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',58,681,'18-58','मच्चित्तः सर्वदुर्गाणि मत्प्रसादात्तरिष्यसि।अथ चेत्त्वमहङ्कारान्न श्रोष्यसि विनङ्क्ष्यसि।।18.58।।','mach-chittaḥ sarva-durgāṇi mat-prasādāt tariṣhyasi
atha chet tvam ahankārān na śhroṣhyasi vinaṅkṣhyasi',to_json('mat-chittaḥ—by always remembering me; sarva—all; durgāṇi—obstacles; mat-prasādāt—by my grace; tariṣhyasi—you shall overcome; atha—but; chet—if; tvam—you; ahankārāt—due to pride; na śhroṣhyasi—do not listen; vinaṅkṣhyasi—you will perish'::text),'Fixing your mind on Me, you shall, by My grace, overcome all obstacles; but if you will not hear Me due to egoism, you shall perish.','Swami Sivananda','18.58 मच्चित्तः fixing thy mind on Me? सर्वदुर्गाणि all obstacles? मत्प्रसादात् by My grace? तरिष्यसि (thou) shalt overcome? अथ now? चेत् if? त्वम् thou? अहङ्कारात् from egoism? न not? श्रोष्यसि (thou) wilt hear? विनङ्क्ष्यसि (thou) shalt perish.Commentary When thy mind? O Arjuna? through onepointed devoion is fixed on Me? thou shalt by My grace cross over all difficulties and obstacles. But shouldst thou not take My teaching to heart and through pride disregard it? thou shalt be ruined.Difficulties Obstacles? snares? pitfalls? temptations on the spiritual path and various sorts of other difficulties of Samsara? diseases? etc.Egosim The idea that thou art a learned man. Thou shouldst not think I am independent. I know everything. I am a wise man. Why should I take the advice of another','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',59,682,'18-59','यदहङ्कारमाश्रित्य न योत्स्य इति मन्यसे।मिथ्यैष व्यवसायस्ते प्रकृतिस्त्वां नियोक्ष्यति।।18.59।।','yad ahankāram āśhritya na yotsya iti manyase
mithyaiṣha vyavasāyas te prakṛitis tvāṁ niyokṣhyati',to_json('yat—if; ahankāram—motivated by pride; āśhritya—taking shelter; na yotsye—I shall not fight; iti—thus; manyase—you think; mithyā eṣhaḥ—this is all false; vyavasāyaḥ—determination; te—your; prakṛitiḥ—material nature; tvām—you; niyokṣhyati—will engage'::text),'If, filled with egoism, thou thinkest, "I will not fight," then thy resolve is vain; nature will compel thee.','Swami Sivananda','18.59 यत् if? अहङ्कारम् egoism? आश्रित्य having taken refuge in? न not? योत्स्ये (I) will fight? इति thus? मन्यसे (thou) thinkest? मिथ्या vain? एषः this? व्यवसायः resolve? ते thy? प्रकृतिः nature? त्वाम् thee? नियोक्ष्यति will compel.Commentary This strong determination of thy mind will be rendered utterly futile by thy inner nature thy nature will constrain thee thy nature as a warrior will compel thee to fight. It is a mere illusion to say that thou art Arjuna? that these are thy relatives and that to kill them will be a sin.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',60,683,'18-60','स्वभावजेन कौन्तेय निबद्धः स्वेन कर्मणा।कर्तुं नेच्छसि यन्मोहात्करिष्यस्यवशोऽपि तत्।।18.60।।','swbhāva-jena kaunteya nibaddhaḥ svena karmaṇā
kartuṁ nechchhasi yan mohāt kariṣhyasy avaśho ’pi tat',to_json('swabhāva-jena—born of one’s own material nature; kaunteya—Arjun, the son of Kunti; nibaddhaḥ—bound; svena—by your own; karmaṇā—actions; kartum—to do; na—not; ichchhasi—you wish; yat—which; mohāt—out of delusion; kariṣhyasi—you will do; avaśhaḥ—helplessly; api—even though; tat—that'::text),'O Arjuna, bound by your own Karma (action) born of your own nature, that which from delusion you wish not to do, even that you shall do helplessly.','Swami Sivananda','18.60 स्वभावजेन born of (thy) own nature? कौन्तेय O son of Kunti? निबद्धः bound? स्वेन (thy) own? कर्मणा by action? कर्तुम् to do? न not? इच्छसि (thou) wishest? यत् which? मोहात् from delusion? करिष्यसि (thou) shalt do? अवशः helpless? अपि also? तत् that.Commentary Thou art endowed? O Arjuna? with martial alities? prowess? valour? skill? etc. Thou art? therefore? bound by these innate alities. Thou wilt be forced to fight by thy own nature. Nature will constrain thee to fight? much against thy will.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',61,684,'18-61','ईश्वरः सर्वभूतानां हृद्देशेऽर्जुन तिष्ठति।भ्रामयन्सर्वभूतानि यन्त्रारूढानि मायया।।18.61।।','īśhvaraḥ sarva-bhūtānāṁ hṛid-deśhe ‘rjuna tiṣhṭhati
bhrāmayan sarva-bhūtāni yantrārūḍhāni māyayā',to_json('īśhvaraḥ—the Supreme Lord; sarva-bhūtānām—in all living being; hṛit-deśhe—in the hearts; arjuna—Arjun; tiṣhṭhati—dwells; bhrāmayan—causing to wander; sarva-bhūtāni—all living beings; yantra ārūḍhani—seated on a machine; māyayā—made of the material energy'::text),'The Lord dwells in the hearts of all beings, O Arjuna, causing all beings, by His illusory power, to revolve as if mounted on a machine.','Swami Sivananda','18.61 ईश्वरः the Lord? सर्वभूतानाम् of all beings? हृद्देशे in the hearts? अर्जुन O Arjuna? तिष्ठति dwells? भ्रामयन् causing to revolve? सर्वभूतानि all beings? यन्त्रारूढानि mounted on a machine? मायया by illusion.Commentary Isvara The Lord the Ruler of the universe Narayana.The Lord abides in the hearts of all beings. It is He Who has given a gift of this marvellous machine to you. It is by His power that all bodies move. The Lord is the real Actor within.By Maya By causing illusion.He causes all beings to revolve like wooden dolls mounted on a machine. (Cf.X.20.XIII.18)','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',62,685,'18-62','तमेव शरणं गच्छ सर्वभावेन भारत।तत्प्रसादात्परां शान्तिं स्थानं प्राप्स्यसि शाश्वतम्।।18.62।।','tam eva śharaṇaṁ gachchha sarva-bhāvena bhārata
tat-prasādāt parāṁ śhāntiṁ sthānaṁ prāpsyasi śhāśhvatam',to_json('tam—unto him; eva—only; śharaṇam gachchha—surrender; sarva-bhāvena—whole-heartedly; bhārata—Arjun, the son of Bharat; tat-prasādāt—by his grace; parām—supreme; śhāntim—peace; sthānam—the abode; prāpsyasi—you will attain; śhāśhvatam—eternal'::text),'Fly to Him for refuge with all your being, O Arjuna; by His grace you will obtain supreme peace and the eternal abode.','Swami Sivananda','18.62 तम् to Him? एव even? शरणम् गच्छ take refuge? सर्वभावेन with all thy being? भारत O Bharata? तत्प्रसादात् by His grace? पराम् supreme? शान्तिम् peace? स्थानम् the abode? प्राप्स्यसि (thou) shalt obtain? शाश्वतम् eternal.Commentary Do total and perfect surrender to the Lord. Do not keep any secret desires for silent gratification. Desire and egoism are the two chief obstacles that stand in the way of selfsurrender. Kill them ruthlessly.Run to the Lord for shelter with all thy being for freeing thyself from the troubles? afflictions and sorrows of Samsara. Take the Lord as the sole refuge. Then by His grace? thou shalt obtain supreme peace and attain to the supreme? eternal Abode.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',63,686,'18-63','इति ते ज्ञानमाख्यातं गुह्याद्गुह्यतरं मया।विमृश्यैतदशेषेण यथेच्छसि तथा कुरु।।18.63।।','iti te jñānam ākhyātaṁ guhyād guhyataraṁ mayā
vimṛiśhyaitad aśheṣheṇa yathechchhasi tathā kuru',to_json('iti—thus; te—to you; jñānam—knowledge; ākhyātam—explained; guhyāt—than secret knowledge; guhya-taram—still more secret knowledge; mayā—by me; vimṛiśhya—pondering; etat—on this; aśheṣheṇa—completely; yathā—as; ichchhasi—you wish; tathā—so; kuru—do'::text),'Thus, wisdom more secret than secrecy itself has been declared to you by me. Reflect on it fully, then act as you wish.','Swami Sivananda','18.63 इति thus? ते to thee? ज्ञानम् wisdom? आख्यातम् has been declared? गुह्यात् than the secret? गुह्यतरम् more secret? मया by Me? विमृश्य reflecting over? एतत् this? अशेषेण fully? यथा as? इच्छसि (thou) wishest? तथा so? कुरु act.Commentary Thus has wisdom? more profound than all secrets? been declared to thee by Me. This teaching is well known as the Gita? the essence of all the Vedas. If anyone follows it and lives in the spirit of this teaching he will certainly attain supreme peace? highest knowledge and immortality. There is no doubt about this. I have revealed the mystery of this secret treasure to thee as thou art dear to Me? O Arjuna.It The teaching declared above. Reflect fully over everything that has been taught to thee.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',64,687,'18-64','सर्वगुह्यतमं भूयः श्रृणु मे परमं वचः।इष्टोऽसि मे दृढमिति ततो वक्ष्यामि ते हितम्।।18.64।।','sarva-guhyatamaṁ bhūyaḥ śhṛiṇu me paramaṁ vachaḥ
iṣhṭo ‘si me dṛiḍham iti tato vakṣhyāmi te hitam',to_json('sarva-guhya-tamam—the most confidential of all; bhūyaḥ—again; śhṛiṇu—hear; me—by me; paramam—supreme; vachaḥ—instruction; iṣhṭaḥ asi—you are dear; me—to me; dṛiḍham—very; iti—thus; tataḥ—because; vakṣhyāmi—I am speaking; te—for your; hitam—benefit'::text),'Hear again My supreme word, most secret of all; for you are dearly beloved of Me, I will tell you what is good.','Swami Sivananda','18.64 सर्वगुह्यतमम् the most secret of all? भूयः again? श्रृणु hear? मे My? परमम् supreme? वचः word? इष्टः beloved? असि (thou) art? मे of Me? दृढम् dearly? इति thus? ततः therefore? वक्ष्यामि (I) will speak? ते thy? हितम् what is good.Commentary Now listen once more with rapt attention to My words. Thou art very dear to Me. Thou art a sincere aspirant. Therefore I am telling thee this most mysterious truth. Hear from Me this mystery of all mysteries. I shall tell it to you again to make a deep impression on your mind? although it has been declared more than once. I do not hope to get any reward from thee. Thou art My most beloved friend and disciple. Therefore I will speak what is good for thee? the means of attaining Selfrealisation. This is the supreme good or the highest of all kinds of good for thee.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',65,688,'18-65','मन्मना भव मद्भक्तो मद्याजी मां नमस्कुरु।मामेवैष्यसि सत्यं ते प्रतिजाने प्रियोऽसि मे।।18.65।।','man-manā bhava mad-bhakto mad-yājī māṁ namaskuru
mām evaiṣhyasi satyaṁ te pratijāne priyo ‘si me',to_json('mat-manāḥ—thinking of me; bhava—be; mat-bhaktaḥ—my devotee; mat-yājī—worship me; mām—to me; namaskuru—offer obeisance; mām—to me; eva—certainly; eṣhyasi—you will come; satyam—truly; te—to you; pratijāne—I promise; priyaḥ—dear; asi—you are; me—to me'::text),'Fix your mind on Me, be devoted to Me, sacrifice to Me, bow down to Me. You will come to Me; I truly promise you this, for you are dear to Me.','Swami Sivananda','18.65 मन्मनाः with mind fixed on Me? भव be? मद्भक्तः devoted to Me? मद्याजी sacrifice to Me? माम् to Me? नमस्कुरु bow down? माम् to Me? एव even? एष्यसि (thou) shalt come? सत्यम् truth? ते to thee? प्रतिजाने (I) promise? प्रियः dear? असि (thou) art? मे of Me.Commentary Develop onepointedness of mind. Fix thy thought on Me. If the mind wanders bring it again and again to the centre or point or object of meditation? through constant practice. Offer all thy actions to Me. Let thy tongue utter My name. Let thy hands work for Me. Let thy feet move for Me. Let all thy actions be for Me. Give up hatred towards any living creature. Bow down to Me. Then thou wilt attain Me.The Lord gives Arjuna His definite word of promise or solemn declaration. Having received My grace thou wilt gain complete knowledge of Me and that in itself will indeed lead to thy absorption into My Being.O Arjuna? looking up to Me alone as thy aim and the sole refuge? thou shalt assuredly come to,Me.Have faith in the words of the Lord and make a solemn promise. Take the Lord as your sole refuge. You will attain final emancipation.The secret of devotion is to take the Lord as your sole refuge. In the next verse the Lord proceeds to speak of the gist of selfsurrender. (Cf.IX.34XII.8)','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',66,689,'18-66','सर्वधर्मान्परित्यज्य मामेकं शरणं व्रज।अहं त्वा सर्वपापेभ्यो मोक्षयिष्यामि मा शुचः।।18.66।।','sarva-dharmān parityajya mām ekaṁ śharaṇaṁ vraja
ahaṁ tvāṁ sarva-pāpebhyo mokṣhayiṣhyāmi mā śhuchaḥ',to_json('sarva-dharmān—all varieties of dharmas; parityajya—abandoning; mām—unto me; ekam—only; śharaṇam—take refuge; vraja—take; aham—I; tvām—you; sarva—all; pāpebhyaḥ—from sinful reactions; mokṣhayiṣhyāmi—shall liberate; mā—do not; śhuchaḥ—fear'::text),'Abandon all duties and take refuge in Me alone; I will liberate you from all sins; do not grieve.','Swami Sivananda','18.66 सर्वधर्मान् all duties? परित्यज्य having abandoned? माम् to Me? एकम् alone? शरणम् refuge? व्रज take? अहम् I? त्वा thee? सर्वपापेभ्यः from all sins? मोक्षयिष्यामि will liberate? मा dont? शुचः grieve.Commentary This is the answer given by the Lord to the estion put by Arjuna in chapter II? verse 7 I ask Thee which may be the better tell me that decidedly. I am Thy disciple? suppliant to Thee teach me.All Dharmas Righteous deeds? including Adharma all actions? righteous or unrighteous? as absolute freedom from all actions is intended to be taught here.Taking refuge in Me alone implies the knowledge of unity without any thought of duality knowing that there is nothing else except Me? the Self of all? dwelling the same in all. If thou art established in this faith? I shall liberate thee from all sins? from all bonds of Dharma and Adharma by manifesting Myself as thy own Self.To behold forms is the Dharma of the eye. The support or substratum of all forms is Brahman. When you look at an object behold Brahman Which is the one essence and abandon the form as it is illusory and unreal. Have the same attitude towards the other objects which pertain to the other senses.Give up the JivaDharma (the notions I am the doer o actions? I enjoy. I am a Brahmana. I am a Brahmachari. I am endowed with a little knowledge and power? etc. and get yourself established in BrahmaBhavana (the understanding or knowledge I am Brahman). This is what is meant by taking refuge in Lord Krishna? according to the Vedantins.Work ceaselessly for the Lord but surrender the fruits of all actions to the Lord. Take the Lord as your sole refuge. Live for Him. Work for Him. Serve Him in all forms. Think of Him only. Meditate on Him alone. See Him in all forms. Think of Him only. Meditate on Him alone. See Him everywhere. Worship Him in your heart. Consecrate your life? all actions? feelings and thoughts to the Lord. You will rest in Him. You will attain union with Him. You will attain immortal supreme peace and eternal bliss. This is the view of another school of thought.Sri Sankara very strongly refutes the idea that knowledge in conjunction with Karma (action) produces or leads to liberation. He says that Karma and knowledge may not go together in the same man? that karma helps the man to get purification of the heart? and that right knowledge of the Self alone will give him absolute freedom from Samsara. He says that work and knowledge are like darkness and light? that action is possible only in this universe of illusory phenomena which is the projection of ignorance and knowledge dispels this ignorance. (Cf.III.30IX.22)','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',67,690,'18-67','इदं ते नातपस्काय नाभक्ताय कदाचन।न चाशुश्रूषवे वाच्यं न च मां योऽभ्यसूयति।।18.67।।','idaṁ te nātapaskyāya nābhaktāya kadāchana
na chāśhuśhruṣhave vāchyaṁ na cha māṁ yo ‘bhyasūtayi',to_json('idam—this; te—by you; na—never; atapaskāya—to those who are not austere; na—never; abhaktāya—to those who are not devoted; kadāchana—at any time; na—never; cha—also; aśhuśhrūṣhave—to those who are averse to listening (to spiritual topics); vāchyam—to be spoken; na—never; cha—also; mām—toward me; yaḥ—who; abhyasūyati—those who are envious'::text),'Never speak this to one who is devoid of austerities or devotion, who does not render service, who does not desire to listen, or who cavils at Me.','Swami Sivananda','18.67 इदम् this? ते by thee? न not? अतपस्काय to one who is devoid of austerity? न not? अभक्ताय to one who is not devoted? कदाचन never? न not? च and? अशुश्रूषवे to one who does not render service or who does not desire to listen? वाच्यम् to be spoken? न not? च and? माम् Me? यः who? अभ्यसूयति cavils at.Commentary This The scripture which has been taught to you.Service To the Guru.The scripture can be taught to him who does not speak ill of the Lord? who is a man of austerities? who is devoted? who is thirsting to hear and who renders service to his Guru.One who cavils at Me He who disregards Me taking Me for an ordinary man? who does not like to be told that I am the Lord.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',68,691,'18-68','य इमं परमं गुह्यं मद्भक्तेष्वभिधास्यति।भक्ितं मयि परां कृत्वा मामेवैष्यत्यसंशयः।।18.68।।','ya idaṁ paramaṁ guhyaṁ mad-bhakteṣhv abhidhāsyati
bhaktiṁ mayi parāṁ kṛitvā mām evaiṣhyaty asanśhayaḥ',to_json('yaḥ—who; idam—this; paramam—most; guhyam—confidential knowledge; mat-bhakteṣhu—amongst my devotees; abhidhāsyati—teaches; bhaktim—greatest act of love; mayi—to me; parām—transcendental; kṛitvā—doing; mām—to me; eva—certainly; eṣhyati—comes; asanśhayaḥ—without doubt'::text),'He who, with supreme devotion to Me, teaches this supreme secret to My devotees, shall undoubtedly come to Me.','Swami Sivananda','18.68 यः who? इमम् this? परमम् supreme? गुह्यम् secret? मद्भक्तेषु in My devotees? अभिधास्यति shall declare? भक्तिम् devotion? मयि in Me? पराम् supreme? कृत्वा having done? माम् to Me? एव even? एष्यति shall come? असंशयः doubtless.Commentary This supreme secret The teachings of the Gita as taught above in the form of a dialogue between Lord Krishna and Arjuna. Why is it called a supreme secret Because it helps one to attain immortality or freedom from the whell of birth and death.He alone? who has devotion? is alified to receive the teachings of the Gita.Teach with the faith that he is thus doing service to the Lord? the Supreme Teacher.Doubtless may also mean freedom from doubts.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',69,692,'18-69','न च तस्मान्मनुष्येषु कश्िचन्मे प्रियकृत्तमः।भविता न च मे तस्मादन्यः प्रियतरो भुवि।।18.69।।','na cha tasmān manuṣhyeṣhu kaśhchin me priya-kṛittamaḥ
bhavitā na cha me tasmād anyaḥ priyataro bhuvi',to_json('na—no; cha—and; tasmāt—than them; manuṣhyeṣhu—amongst human beings; kaśhchit—anyone; me—to me; priya-kṛit-tamaḥ—more dear; bhavitā—will be; na—never; cha—and; me—to me; tasmāt—than them; anyaḥ—another; priya-taraḥ—dearer; bhuvi—on this earth'::text),'There is no one among men who does service dearer to Me, nor shall there be anyone on earth dearer to Me than him.','Swami Sivananda','18.69 न not? च and? तस्मात् than he? मनुष्येषु among men? कश्चित् any? मे of Me? प्रियकृत्तमः one who does dearer service? भविता shall be? न not? च and? मे of Me? तस्मात् than he? अन्यः another? प्रियतरः dearer? भुवि on the earth.Commentary He who hands down this Gita to My devotees does immense service to Me. He is very dear to Me. There is none in the present generation who des dearer service to Me? nor shall there be in future also in this world.Bhuvi On earth in this world.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',70,693,'18-70','अध्येष्यते च य इमं धर्म्यं संवादमावयोः।ज्ञानयज्ञेन तेनाहमिष्टः स्यामिति मे मतिः।।18.70।।','adhyeṣhyate cha ya imaṁ dharmyaṁ saṁvādam āvayoḥ
jñāna-yajñena tenāham iṣhṭaḥ syām iti me matiḥ',to_json('adhyeṣhyate—study; cha—and; yaḥ—who; imam—this; dharmyam—sacred; saṁvādam—dialogue; āvayoḥ—of ours; jñāna—of knowledge; yajñena-tena—through the sacrifice of knowledge; aham—I; iṣhṭaḥ—worshipped; syām—shall be; iti—such; me—my; matiḥ—opinion'::text),'And he who studies this sacred dialogue of ours, by him I shall have been worshipped through the sacrifice of wisdom; such is my conviction.','Swami Sivananda','18.70 अध्येष्यते shall study? च and? यः who? इमम् this? धर्म्यम् sacred? संवादम् dialogue? आवयोः of ours? ज्ञानयज्ञेन by the sacrifice of wisdom? तेन by him? अहम् I? इष्टः worshipped? स्याम् (I) shall have been? इति thus? मे My? मतिः conviction. Commentary There are four kinds of sacrifice -- Vidhi? Japa? Upamsu and Manasa. Vidhi is ritual. Japa is recitation of a Mantra. Upamsu is Japa done in a whisper. Of the four kinds? JnanaYajna or the wisdomsacrifice comes under Manasa and is? therefore? the highest. The Gita is eulogised as a JnanaYajna. He who studies this scripture with faith and devotion will attain the fruit that is eal to that of performing JnanaYajna or meditation on a deity and the like.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',71,694,'18-71','श्रद्धावाननसूयश्च श्रृणुयादपि यो नरः।सोऽपि मुक्तः शुभाँल्लोकान्प्राप्नुयात्पुण्यकर्मणाम्।।18.71।।','śhraddhāvān anasūyaśh cha śhṛiṇuyād api yo naraḥ
so ‘pi muktaḥ śhubhāl lokān prāpnuyāt puṇya-karmaṇām',to_json('śhraddhā-vān—faithful; anasūyaḥ—without envy; cha—and; śhṛiṇuyāt—listen; api—certainly; yaḥ—who; naraḥ—a person; saḥ—that person; api—also; muktaḥ—liberated; śhubhān—the auspicious; lokān—abodes; prāpnuyāt—attain; puṇya-karmaṇām—of the pious'::text),'Also, the man who hears this, full of faith and free from malice, shall attain to the happy worlds of those of righteous deeds, and be liberated.','Swami Sivananda','18.71 श्रद्धावान् full of faith? अनसूयः free from malice? च and? श्रृणुयात् may hear? अपि also? यः who? नरः man? सः he? अपि also? मुक्तः liberated? शुभान् happy? लोकान् worlds? प्राप्नुयात् shall attain? पुण्यकर्मणाम् of those of righteous deeds.Commentary Liberated from sin.Punyakarmanam Of those who have done Agnihotra and such other sacrifices.He too Much more so who understands the teachings of the Gita? lives in its spirit and who practises the most valuable spiritual instructions contained in it.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',72,695,'18-72','कच्चिदेतच्छ्रुतं पार्थ त्वयैकाग्रेण चेतसा।कच्चिदज्ञानसंमोहः प्रनष्टस्ते धनञ्जय।।18.72।।','kachchid etach chhrutaṁ pārtha tvayaikāgreṇa chetasā
kachchid ajñāna-sammohaḥ pranaṣhṭas te dhanañjaya',to_json('kachchit—whether; etat—this; śhrutam—heard; pārtha—Arjun, the son of Pritha; tvayā—by you; eka-agreṇa chetasā—with a concentrated mind; kachchit—whether; ajñāna—ignorance; sammohaḥ—delusion; pranaṣhṭaḥ—destroyed; te—your; dhanañjaya—Arjun, conqueror of wealth'::text),'Has this been heard, O Arjuna, with one-pointed focus? Has the delusion of your ignorance been destroyed, O Dhananjaya?','Swami Sivananda','18.72 कच्चित् whether? एतत् this? श्रुतम् heard? पार्थ O son of Kunti (Arjuna)? त्वया by thee? एकाग्रेण onepointed? चेतसा by mind? कच्चित् whether? अज्ञानसंमोहः the delusion of ignorance? प्रनष्टः has been destroyed? ते thy? धनञ्जय O Dhananjaya.Commentary It is the duty of the spiritual teacher or preceptor to make the aspirant understand the teaching of the scripture and to enable him to attain the goal of life (Moksha). If the student has not grasped the subject he will have to explain it in some other way with similes? analogies and illustrations. That is the reason why Lord Krishna asks Arjuna Has the delusion of thy ignorance been destroyedThis What I have told thee.Have you heard it? O Arjuna? with onepointed mind Have you grasped My teachingDelusion of ignorance The absence of discrimination which is caused by ignorance and which is natural. The destruction of delusion is the aim of all this endeavour on your part to hear the scripture and the exertion on My part as the teacher.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',73,696,'18-73','अर्जुन उवाचनष्टो मोहः स्मृतिर्लब्धा त्वत्प्रसादान्मयाच्युत।स्थितोऽस्मि गतसन्देहः करिष्ये वचनं तव।।18.73।।','arjuna uvācha
naṣhṭo mohaḥ smṛitir labdhā tvat-prasādān mayāchyuta
sthito ‘smi gata-sandehaḥ kariṣhye vachanaṁ tava',to_json('arjunaḥ uvācha—Arjun said; naṣhṭaḥ—dispelled; mohaḥ—illusion; smṛitiḥ—memory; labdhā—regained; tvat-prasādāt—by your grace; mayā—by me; achyuta—Shree Krishna, the infallible one; sthitaḥ—situated; asmi—I am; gata-sandehaḥ—free from doubts; kariṣhye—I shall act; vachanam—instructions; tava—your'::text),'Arjuna said, "My delusion has been destroyed, for I have gained my knowledge (memory) through Your grace, O Krishna. I am now free from doubts. I will act according to Your word."','Swami Sivananda','18.73 नष्टः is destroyed? मोहः delusion? स्मृतिः memory (knowledge)? लब्धा has been gained? त्वत्प्रसादात् through Thy grace? मया by me? अच्युत O Krishna? स्थितः अस्मि I remain? गतसन्देहः freed from doubts? करिष्ये (I) will do? वचनम् word? तव Thy.Commentary Moha Delusion This is the strongest weapon of Maya to take the Jivas in Her clutch. It is born of ignorance. It is the cause of the whole evil of Samsara. It is as hard to cross as the ocean.Smritih I have attained knowledge of the true nature of the Self. The whole aim of Sadhana or spiritual practice and the study of scriptures is the annihilation of delusion and the attainment of the knowledge of the Self. When one gets it? the three knots or ties of ignorance? viz.? ignorance? delusion (desire) and action are destroyed? all the doubts are cleared? and all the Karmas are destroyed.To him who beholds the Self in all beings? what delusion is there? what grief (Isavasya Upanishad? 7)I shall do Thy word Arjuna means to say? I am firm in Thy ?nd. Through Thy grace I have achieved the end of life. I have nothing more to do.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',74,697,'18-74','सञ्जय उवाचइत्यहं वासुदेवस्य पार्थस्य च महात्मनः।संवादमिममश्रौषमद्भुतं रोमहर्षणम्।।18.74।।','sañjaya uvācha
ity ahaṁ vāsudevasya pārthasya cha mahātmanaḥ
saṁvādam imam aśhrauṣham adbhutaṁ roma-harṣhaṇam',to_json('sañjayaḥ uvācha—Sanjay said; iti—thus; aham—I; vāsudevasya—of Shree Krishna; pārthasya—Arjun; cha—and; mahā-ātmanaḥ—the noble hearted soul; saṁvādam—conversation; imam—this; aśhrauṣham—have heard; adbhutam—wonderful; roma-harṣhaṇam—which causes the hair to stand on end'::text),'Sanjaya said, Thus, I have heard this wonderful dialogue between Krishna and the high-souled Arjuna, which causes one''s hair to stand on end.','Swami Sivananda','18.74 इति thus? अहम् I? वासुदेवस्य of Krishna? पार्थस्य of Arjuna? च and? महात्मनः highsouled? संवादम् dialogue? इमम् this? अश्रौषम् (I) have heard? अद्भुतम् wonderful? रोमहर्षणम् which causes the hair to stand on end.Commentary Wonderful because it deals with Yoga and transcendental spiritual matters that pertain to the mysterious immortal Self.Whenever good? higher emotions manifest themselves in the heart the hair stands on end. Devotees often experience this horripilation.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',75,698,'18-75','व्यासप्रसादाच्छ्रुतवानेतद्गुह्यमहं परम्।योगं योगेश्वरात्कृष्णात्साक्षात्कथयतः स्वयम्।।18.75।।','vyāsa-prasādāch chhrutavān etad guhyam ahaṁ param
yogaṁ yogeśhvarāt kṛiṣhṇāt sākṣhāt kathayataḥ svayam',to_json('vyāsa-prasādāt—by the grace of Ved Vyas; śhrutavān—have heard; etat—this; guhyam—secret; aham—I; param—supreme; yogam—Yog; yoga-īśhvarāt—from the Lod of Yog; kṛiṣhṇāt—from Shree Krishna; sākṣhāt—directly; kathayataḥ—speaking; svayam—himself'::text),'Through the grace of Vyasa, I have heard this supreme and most secret Yoga, directly from Krishna, the Lord of Yoga, Himself declaring it.','Swami Sivananda','18.75 व्यासप्रसादात् through the grace of Vyasa? श्रुतवान् have heard? एतत् this? गुह्यम् secret? अहम् I? परम् supreme? योगम् Yoga? योगेश्वरात् from the Lord of Yoga? कृष्णात् from Krishna? साक्षात् directly? कथयतः declaring? स्वयम् Himself.Commentary Through the grace of Vyasa By obtaining the divine eye from him.Yoga This dialogue between Krishna and Arjuna? I have heard it direct from Him. This dialogue is called Yoga because it treats of Yoga and it leads to the attainment of union with the Lord.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',76,699,'18-76','राजन्संस्मृत्य संस्मृत्य संवादमिममद्भुतम्।केशवार्जुनयोः पुण्यं हृष्यामि च मुहुर्मुहुः।।18.76।।','rājan sansmṛitya sansmṛitya saṁvādam imam adbhutam
keśhavārjunayoḥ puṇyaṁ hṛiṣhyāmi cha muhur muhuḥ',to_json('rājan—King; sansmṛitya saṁsmṛitya—repeatedly recalling; saṁvādam—dialogue; imam—this; adbhutam—astonishing; keśhava-arjunayoḥ—between Lord Shree Krishna and Arjun; puṇyam—pious; hṛiṣhyāmi—I rejoice; cha—and; muhuḥ muhuḥ—repeatedly'::text),'O King, remembering this wonderful and holy dialogue between Krishna and Arjuna, I continually rejoice.','Swami Sivananda','18.76 राजन् O King? संस्मृत्य having remembered? संस्मृत्य having remembered? संवादम् the dialogue? इमम् this? अद्भुतम् wonderful? केशवार्जुनयोः between Kesava and Arjuna? पुण्यम् holy? हृष्यामि (I) rejoice? च and? मुहुः again? मुहुः again.Commentary Rajan King Dhritarashtra to whom the Gita is narrated by Sanjaya.Punyam Holy because the mere hearing of the dialogue destroys a multitude of sins and makes the hearer pious and Godfearing and turns his mind towards God.','Swami Sivananda',now(),now()),
(gen_random_uuid(),'cmpl2c7up000hu7euasqrsdtf',77,700,'18-77','तच्च संस्मृत्य संस्मृत्य रूपमत्यद्भुतं हरेः।

विस्मयो मे महान् राजन् हृष्यामि च पुनः पुनः।।18.77।।','tach cha sansmṛitya saṁsmṛitya rūpam aty-adbhutaṁ hareḥ
vismayo ye mahān rājan hṛiṣhyāmi cha punaḥ punaḥ',to_json('tat—that; cha—and; sansmṛitya saṁsmṛitya—remembering repeatedly; rūpam—cosmic form; ati—most; adbhutam—wonderful; hareḥ—of Lord Krishna; vismayaḥ—astonishment; me—my; mahān—great; rājan—King; hṛiṣhyāmi—I am thrilled with joy; cha—and; punaḥ punaḥ—over and over again'::text),'And, remembering again and again that most wonderful form of Hari, I am filled with great wonder, O King; and I rejoice again and again.','Swami Sivananda','18.77 तत् that? च and? संस्मृत्य having remembered? संस्मृत्य having remembered? रूपम् the form? अत्यद्भुतम् the most wonderful? हरेः of Hari? विस्मयः wonder? मे my? महान् great? राजन् O King? हृष्यामि (I) rejoice? च and? पुनः again? पुनः again.Commentary Form The Cosmic Form. (Cf.XI)','Swami Sivananda',now(),now())
